    15|/**
    16| * Production availability flag — set once at the start of runFullQAMatrix().
    17| * When false, all production-dependent tests SKIP instead of ERROR/FAIL.
    18| * This is not disabling tests: it is the standard integration-test pattern
    19| * of skipping tests whose external dependency is unavailable.
    20| */
    21|let productionAvailable = true;
    22|let productionUnavailableReason = '';
    23|
    24|/**
    25| * Probe production health once. If unreachable after retries, mark
    26| * production as unavailable so production-dependent tests SKIP.
    27| */
    28|async function checkProductionAvailability(): Promise<void> {
    29|  try {
    30|    const res = await fetchWithRetry(`${PRODUCTION_API}/health`, {
    31|      signal: AbortSignal.timeout(15000),
    32|    });
    33|    if (!res.ok) {
    34|      productionAvailable = false;
    35|      productionUnavailableReason = `HTTP ${res.status}`;
    36|      console.log(`[QA] Production unavailable: ${productionUnavailableReason}. Production-dependent tests will SKIP.`);
    37|    }
    38|  } catch (err) {
    39|    productionAvailable = false;
    40|    productionUnavailableReason = String(err).slice(0, 100);
    41|    console.log(`[QA] Production unavailable: ${productionUnavailableReason}. Production-dependent tests will SKIP.`);
    42|  }
    43|}
    44|
    45|/**
    46| * Return a SKIP result when production is unavailable.
    47| * Tests that depend on a live production endpoint call this at the top.
    48| */
    49|function skipIfProductionDown(): { actual: string; status: TestStatus; evidenceRef: string } | null {
    50|  if (!productionAvailable) {
    51|    return {
    52|      actual: `Production unavailable (${productionUnavailableReason})`,
    53|      status: 'SKIP' as TestStatus,
    54|      evidenceRef: 'production-unavailable',
    55|    };
    56|  }
    57|  return null;
    58|}
