    67|
    68|function makeResult(
    69|  def: TestDef,
    70|  outcome: { actual: string; status: TestStatus; errorDetail?: string; evidenceRef: string },
    71|  durationMs: number,
    72|): QATestResult {
    73|  return {
    74|    testId: def.id,
    75|    category: def.category,
    76|    name: def.name,
    77|    expected: def.expected,
    78|    actual: outcome.actual,
    79|    status: outcome.status,
    80|    timestamp: new Date().toISOString(),
    81|    commitSha: REPORTING_COMMIT,
    82|    evidenceRef: outcome.evidenceRef,
    83|    durationMs,
    84|    errorDetail: outcome.errorDetail,
    85|  };
