    88|async function runTest(def: TestDef): Promise<QATestResult> {
    89|  const start = Date.now();
    90|  try {
    91|    const outcome = await def.fn();
    92|    return makeResult(def, outcome, Date.now() - start);
    93|  } catch (err) {
    94|    return makeResult(
    95|      def,
    96|      {
    97|        actual: 'Exception thrown',
    98|        status: 'ERROR',
    99|        errorDetail: String(err).slice(0, 500),
   100|        evidenceRef: 'exception',
   101|      },
   102|      Date.now() - start,
   103|    );
   104|  }
