   107|/**
   108| * Fetch JSON with retry on transient errors (502/503/504/connection reset).
   109| * Render instances cycle during deploys, causing brief 502 windows.
   110| * Retries up to 3 times with exponential backoff.
   111| */
   112|async function fetchJson(url: string, opts?: RequestInit): Promise<Record<string, unknown>> {
   113|  const maxRetries = 3;
   114|  let lastErr: Error | null = null;
   115|  for (let attempt = 0; attempt < maxRetries; attempt++) {
   116|    try {
   117|      const res = await fetch(url, { ...opts, signal: AbortSignal.timeout(15000) });
   118|      if (res.status >= 502 && res.status <= 504 && attempt < maxRetries - 1) {
   119|        await new Promise(r => setTimeout(r, (attempt + 1) * 2000));
   120|        continue;
   121|      }
   122|      if (!res.ok) throw new Error(`HTTP ${res.status} ${res.statusText}`);
   123|      return (await res.json()) as Record<string, unknown>;
   124|    } catch (err) {
   125|      lastErr = err as Error;
   126|      if (attempt < maxRetries - 1) {
   127|        await new Promise(r => setTimeout(r, (attempt + 1) * 2000));
   128|        continue;
   129|      }
   130|    }
   131|  }
   132|  throw lastErr ?? new Error('fetchJson exhausted retries');
   133|}
