   135|/**
   136| * Get owner token from env var or local file.
   137| * Returns null if unavailable (e.g. in CI without secrets).
   138| * Tests using this should SKIP gracefully when null.
   139| */
   140|function getOwnerToken(): string | null {
   141|  if (process.env.IVX_OWNER_TOKEN) return process.env.IVX_OWNER_TOKEN;
   142|  const tokenPath = join(process.cwd(), 'tmp', 'owner_token.txt');
   143|  if (existsSync(tokenPath)) {
   144|    return readFileSync(tokenPath, 'utf8').trim();
   145|  }
   146|  return null;
   147|}
