   149|/**
   150| * Fetch with retry on transient errors (502/503/504).
   151| * Returns the Response object so callers can check status codes.
   152| */
   153|async function fetchWithRetry(url: string, opts?: RequestInit): Promise<Response> {
   154|  const maxRetries = 3;
   155|  let lastRes: Response | null = null;
   156|  for (let attempt = 0; attempt < maxRetries; attempt++) {
   157|    try {
   158|      const res = await fetch(url, { ...opts, signal: AbortSignal.timeout(15000) });
   159|      if (res.status >= 502 && res.status <= 504 && attempt < maxRetries - 1) {
   160|        await new Promise(r => setTimeout(r, (attempt + 1) * 2000));
   161|        continue;
   162|      }
   163|      return res;
   164|    } catch (err) {
   165|      if (attempt < maxRetries - 1) {
   166|        await new Promise(r => setTimeout(r, (attempt + 1) * 2000));
   167|        continue;
   168|      }
   169|      throw err;
   170|    }
   171|  }
   172|  return lastRes ?? new Response('', { status: 503 });
   173|}
