   175|function hashString(s: string): string {
   176|  let h = 0;
   177|  for (let i = 0; i < s.length; i++) {
   178|    h = ((h << 5) - h + s.charCodeAt(i)) | 0;
   179|  }
   180|  return `h${(h >>> 0).toString(16)}`;
